#!/usr/bin/env bash
# Integer and float scalars give the same bits under `#` (the evaluator) as in the
# program's own code. tests/cases/eval-parity/*.ab were generated by
# tools/gen-eval-parity.py (deleted; they are now the source); each computes its cases both ways and exits 42 when
# every pair of strings matches (it prints the first differing cases otherwise).
set -euo pipefail

compiler=${1:-build/ablac.bin}
project_root=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
output_directory="$project_root/build/eval-parity"
mkdir -p "$output_directory"

for source in "$project_root"/tests/cases/eval-parity/*.ab; do
    name=$(basename "$source" .ab)
    "$compiler" build "$source" -o "$output_directory/$name" --fast --no-cache
    set +e
    "$output_directory/$name"
    status=$?
    set -e
    [[ $status -eq 42 ]] || { echo "eval-parity: $name differs" >&2; exit 1; }
done
echo "eval parity: scalars match between the evaluator and native code"
